1	import { redirect, notFound } from "next/navigation";
2	import { headers } from "next/headers";
3	
4	/**
5	 * Host gate: the admin portal is only reachable from the dedicated admin
6	 * hostname(s) in NXEON_ADMIN_HOSTS (comma-separated). On any other host — e.g.
7	 * the public nxeon.cloud — /admin 404s as if it doesn't exist. Empty/unset =
8	 * no host restriction (dev fallback). Returns true when access should be REFUSED.
9	 */
10	async function adminHostBlocked(): Promise<boolean> {
11	  const allow = (process.env.NXEON_ADMIN_HOSTS ?? "")
12	    .split(",").map((s) => s.trim().toLowerCase()).filter(Boolean);
13	  if (allow.length === 0) return false;
14	  const host = ((await headers()).get("host") ?? "").toLowerCase().split(":")[0];
15	  return !allow.includes(host);
16	}
17	import { realUser, impersonating } from "@/lib/auth";
18	import { isStaff, canAccessHref } from "@/lib/rbac";
19	import { db } from "@/lib/db";
20	import { getSetting, getSettingBool } from "@/lib/settings";
21	import { Shell, type NavSection } from "@/components/portal/Shell";
22	import { ADMIN_NAV } from "@/lib/admin-groups";
23	import { AdminSubTabs } from "@/components/admin/SubTabs";
24	
25	/** Loose sanity check for a literal IPv4/IPv6 address (no CIDR / ranges). */
26	function isPlainIp(s: string): boolean {
27	  return /^\d{1,3}(\.\d{1,3}){3}$/.test(s) || (s.includes(":") && /^[0-9a-fA-F:]+$/.test(s));
28	}
29	
30	/**
31	 * IP allow-list gate for /admin. `allowed_admin_ips` is a comma-separated list of
32	 * literal IPs; empty = no restriction. Fails OPEN (allows) when the list has no
33	 * parseable entries or the requester IP can't be determined, so a bad value can
34	 * never lock every admin out — only an exact match is ever enforced.
35	 * Returns true when access should be REFUSED.
36	 */
37	async function adminIpBlocked(): Promise<boolean> {
38	  const raw = await getSetting("allowed_admin_ips", "");
39	  const entries = raw.split(",").map((s) => s.trim()).filter(Boolean);
40	  if (entries.length === 0) return false; // no restriction configured
41	  const valid = entries.filter(isPlainIp);
42	  if (valid.length === 0) {
43	    console.warn("[admin-ip] allowed_admin_ips is set but has no valid IPs; failing open:", raw);
44	    return false; // malformed -> fail open
45	  }
46	  const hdrs = await headers();
47	  // Trust nginx's X-Real-IP ($remote_addr), which the client cannot forge. Fall
48	  // back to the LAST X-Forwarded-For hop (the one our proxy appended), never the
49	  // client-supplied leftmost entry.
50	  const xff = (hdrs.get("x-forwarded-for") ?? "").split(",").map((s) => s.trim()).filter(Boolean);
51	  const ip = hdrs.get("x-real-ip")?.trim() || xff[xff.length - 1] || "";
52	  if (!ip) {
53	    console.warn("[admin-ip] could not determine requester IP; failing open");
54	    return false;
55	  }
56	  return !valid.includes(ip);
57	}
58	
59	export default async function AdminLayout({ children }: { children: React.ReactNode }) {
60	  // Wrong host (e.g. public nxeon.cloud) → 404, so /admin isn't reachable there.
61	  if (await adminHostBlocked()) notFound();
62	
63	  const user = await realUser();
64	  if (!user) redirect("/login");
65	  if (!isStaff(user.role)) redirect("/dashboard");
66	  const imp = await impersonating();
67	  if (imp) redirect("/dashboard"); // exit impersonation before using admin tools
68	
69	  // IP allow-list: refuse admin access from an IP that isn't explicitly allowed.
70	  if (await adminIpBlocked()) {
71	    return (
72	      <main
73	        style={{
74	          minHeight: "100vh",
75	          display: "flex",
76	          flexDirection: "column",
77	          alignItems: "center",
78	          justifyContent: "center",
79	          gap: "0.75rem",
80	          padding: "2rem",
81	          textAlign: "center",
82	        }}
83	      >
84	        <h1 style={{ fontSize: "1.5rem", fontWeight: 600 }}>Access restricted</h1>
85	        <p style={{ maxWidth: "32rem", opacity: 0.8 }}>
86	          The admin console isn&apos;t available from your current network.
87	        </p>
88	      </main>
89	    );
90	  }
91	
92	  // Staff 2FA enforcement: when enabled, staff without TOTP must set it up before
93	  // using admin tools. Redirect (don't hard-fail) to their security settings so
94	  // they can enroll, then come back.
95	  if ((await getSettingBool("enforce_staff_2fa", false)) && !user.totpEnabled) {
96	    redirect("/dashboard/settings?require2fa=1");
97	  }
98	
99	  // Filter every entry's members down to what this role can access, drop entries
100	  // that end up empty, then drop sections that end up empty. An entry always
101	  // links to (and its sub-tab bar always starts at) its first *accessible*
102	  // member, so no role is ever handed a link that just bounces it to /admin.
103	  const visibleSections = ADMIN_NAV.map((section) => ({
104	    ...section,
105	    entries: section.entries
106	      .map((entry) => ({
107	        ...entry,
108	        tabs: entry.tabs.filter((tab) => canAccessHref(user.role, tab.href)),
109	      }))
110	      .filter((entry) => entry.tabs.length > 0),
111	  })).filter((section) => section.entries.length > 0);
112	
113	  // Flat list of every href this role may reach — handed to <AdminSubTabs /> so
114	  // the in-page tab bars hide the same members the sidebar does.
115	  const allowedHrefs = visibleSections.flatMap((s) =>
116	    s.entries.flatMap((e) => e.tabs.map((t) => t.href))
117	  );
118	
119	  const notifications = await db.notification.findMany({
120	    where: { userId: user.id },
121	    orderBy: { createdAt: "desc" },
122	    take: 15,
123	  });
124	
125	  // Attention-count badges for the sidebar. Each count fails soft (→ 0) so a
126	  // missing model/table can never break the admin layout.
127	  const soft = (p: Promise<number>) => p.catch(() => 0);
128	  const [chatUnread, ticketsAwaiting, abuseOpen, feedbackNew, improvementsProposed] = await Promise.all([
129	    // Live chat: conversations flagged unread for agents (same "needs a reply"
130	    // signal the chat inbox sorts/counts by — ChatConversation.unreadForAgent).
131	    soft(db.chatConversation.count({ where: { unreadForAgent: true } })),
132	    // Support desk: tickets awaiting a staff reply (open + customer replies),
133	    // matching the "Awaiting staff" stat on /admin/support.
134	    soft(db.ticket.count({ where: { status: { in: ["OPEN", "CUSTOMER_REPLY"] } } })),
135	    // Abuse queue: alerts still OPEN.
136	    soft(db.abuseAlert.count({ where: { status: "OPEN" } })),
137	    // Feedback: new (untriaged) reports.
138	    soft(db.feedback.count({ where: { status: "NEW" } })),
139	    // Improvements board: proposals awaiting the owner's approve/decline.
140	    soft(db.improvement.count({ where: { status: "PROPOSED" } })),
141	  ]);
142	
143	  // Per-route attention counts, unchanged in meaning from the flat sidebar.
144	  const badges: Record<string, number> = {
145	    "/admin/chat": chatUnread,
146	    "/admin/support": ticketsAwaiting,
147	    "/admin/abuse": abuseOpen,
148	    "/admin/feedback": feedbackNew,
149	    "/admin/improvements": improvementsProposed,
150	  };
151	  // Build the sidebar: one icon'd row per top-level ENTRY, grouped into labelled
152	  // sections. Secondary members ride along as `children` — the sidebar never
153	  // expands them (they're the page's sub-tabs), but they keep the parent row
154	  // highlighted while you're on one and keep ⌘K able to reach every route.
155	  // Attention counts ROLL UP: an entry shows the sum of its members' badges, and
156	  // <AdminSubTabs /> repeats each member's own count on its tab.
157	  const nav: NavSection[] = visibleSections.map((section) => ({
158	    label: section.label,
159	    items: section.entries.map((entry) => {
160	      const rollup = entry.tabs.reduce((sum, tab) => sum + (badges[tab.href] ?? 0), 0);
161	      return {
162	        label: entry.label,
163	        href: entry.tabs[0].href,
164	        icon: entry.icon,
165	        badge: rollup > 0 ? rollup : undefined,
166	        children: entry.tabs.map((tab) => ({
167	          label: tab.label,
168	          href: tab.href,
169	          badge: badges[tab.href] > 0 ? badges[tab.href] : undefined,
170	        })),
171	      };
172	    }),
173	  }));
174	
175	  return (
176	    <Shell
177	      nav={nav}
178	      tag="ops"
179	      user={{ name: user.name, email: user.email, role: user.role, balanceCents: user.balanceCents }}
180	      notifications={notifications.map((n) => ({
181	        id: n.id,
182	        title: n.title,
183	        body: n.body,
184	        href: n.href,
185	        readAt: n.readAt ? n.readAt.toISOString() : null,
186	        createdAt: n.createdAt.toISOString(),
187	      }))}
188	    >
189	      {/* Sub-navigation for the consolidated entries, mounted once here so every
190	          grouped page gets its tab bar without per-page wiring. Renders nothing
191	          for single-member entries. */}
192	      <AdminSubTabs badges={badges} allowed={allowedHrefs} />
193	      {children}
194	    </Shell>
195	  );
196	}
