59	async function audit(userId: string | null, action: string, detail?: string) {
60	  // Attribute to the real admin when an admin is impersonating, so customer-scoped
61	  // actions taken during impersonation aren't logged as if the customer did them.
62	  const imp = await impersonating();
63	  const actor = imp ? `actingAdmin=${imp.admin.id}` : "";
64	  const fullDetail = detail && actor ? `${detail} ${actor}` : detail || actor || undefined;
65	  await db.auditLog.create({ data: { userId, action, detail: fullDetail } });
