68	/**
69	 * Grant the configured signup free credit to a freshly-registered user, once.
70	 * No-op when the amount is 0 or the account already has signup credit.
71	 *
72	 * PRIVATE ON PURPOSE. This used to be an export of lib/actions-growth.ts — a
73	 * `"use server"` file — which made "credit an arbitrary `userId`" a public
74	 * network endpoint whose only defence was a guard that inspected request
75	 * headers. It has exactly one caller, `register` below, and a function with one
76	 * in-process caller has no business being an endpoint at all. Keeping it here,
77	 * unexported, is the same reasoning that moved `safeNext` and
78	 * `verifyTotpForUser` out of `"use server"` files.
79	 *
80	 * It also removes a live fragility: the old guard resolved the acting account
81	 * from the session, and `register` calls this immediately after minting that
82	 * session, so the grant's success depended on request-scoped session state
83	 * settling mid-action. Nothing about "did this new account already get its
84	 * welcome credit?" needs the session — `signupCreditCents` on the row is the
85	 * only fact that matters, and it is what makes the grant idempotent.
86	 */
87	async function grantSignupCredit(userId: string): Promise<number> {
88	  // Prefer the admin-editable setting (`signup_free_credit_cents`); fall back to
89	  // the legacy SIGNUP_FREE_CREDIT_CENTS env default when the setting is unset.
90	  const cents = await getSettingInt("signup_free_credit_cents", signupFreeCreditCents());
91	  if (cents <= 0) return 0;
92	  // Idempotent claim: only ever grants against a row that has no signup credit
93	  // yet, so a retry (or two concurrent registrations of the same account, which
94	  // the unique email index already prevents) cannot pay twice.
95	  const claimed = await db.user.updateMany({
96	    where: { id: userId, signupCreditCents: 0 },
97	    data: { balanceCents: { increment: cents }, signupCreditCents: cents },
98	  });
99	  if (claimed.count === 0) return 0;
100	  await db.walletTransaction.create({
101	    data: { userId, amountCents: cents, description: "Welcome credit" },
102	  });
103	  return cents;
104	}
