116	const credsSchema = z.object({
117	  email: z.string().max(200).email("Enter a valid email address"),
118	  password: z.string().min(8).max(200),
119	});
120	
121	export async function register(prev: any, formData: FormData): Promise<{ error?: string }> {
122	  const parsed = credsSchema
123	    .extend({
124	      name: z.string().min(1, "Enter your name").max(100, "Name is too long"),
125	      password: z
126	        .string()
127	        .min(8, "Password must be at least 8 characters")
128	        .max(200, "Password is too long")
129	        .regex(/[a-zA-Z]/, "Password must include a letter")
130	        .regex(/[0-9]/, "Password must include a number"),
131	    })
132	    .safeParse({
133	    // Canonicalise BEFORE validating, so `  Alice@Example.com ` is stored in the
134	    // one form every lookup will use. See lib/email-normalize.ts.
135	    email: normalizeEmail(formData.get("email")),
136	    password: formData.get("password"),
137	    name: formData.get("name"),
138	  });
139	  // Say what is actually wrong. This used to collapse four precise, already
140	  // written messages into "Enter a valid email, name, and password (min 8
141	  // chars)." — so a customer whose only problem was a missing digit was told
142	  // about a length rule their 8-character password already satisfied, and had
143	  // no way to work out what the form wanted. The deploy path (`payAndDeploy`
144	  // below, via lib/order.ts) has surfaced the real issue since it was written;
145	  // this is the same one line.
146	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Check the form and try again." };
147	  const { email, password, name } = parsed.data;
148	
149	  // Throttle signups per email+IP (reuses the login rate-limit helper) to curb
150	  // automated account creation and welcome-credit farming.
151	  const regIp = clientIp(await headers());
152	  const regRl = checkRateLimit(`register:${email}:${regIp}`, { max: 5, windowMs: 15 * 60 * 1000 });
153	  if (!regRl.ok) return { error: `Too many attempts. Try again in ${regRl.retryAfterSec}s.` };
154	
155	  const existing = await db.user.findUnique({ where: { email } });
156	  if (existing) return { error: "An account with that email already exists." };
157	
158	  // Capture a referral from the `ref` cookie (set by the register page) if the
159	  // code maps to a real user. Self-referral is impossible here (new account).
160	  const jar = await cookies();
161	  const refCode = jar.get(REF_COOKIE)?.value?.trim().toUpperCase();
162	  let referredById: string | null = null;
163	  if (refCode) {
164	    const referrer = await db.user.findUnique({ where: { referralCode: refCode } });
165	    if (referrer) referredById = referrer.id;
166	  }
167	
168	  const referralCode = await uniqueReferralCode();
169	  const user = await db.user.create({
170	    data: {
171	      email,
172	      name,
173	      passwordHash: await bcrypt.hash(password, 12),
174	      referralCode,
175	      referredById,
176	    },
177	  });
178	  await audit(user.id, "user.register", referredById ? `ref=${refCode}` : undefined);
179	  await createSession(user.id);
180	  // Grant signup free credit (no-op unless the configured amount is > 0).
181	  //
182	  // Still non-fatal — a failure here must not cost the customer the account they
183	  // just created — but no longer SILENT. `signup_free_credit_cents` is an
184	  // admin-editable field that the settings panel reports "Saved." for, and an
185	  // empty `catch {}` here is exactly how this codebase has repeatedly ended up
186	  // with a control that reports success and does nothing. If the grant fails,
187	  // that fact is now in the logs and there is a wallet row to reconcile against.
188	  try {
189	    await grantSignupCredit(user.id);
190	  } catch (e) {
191	    console.error("[register] signup credit grant failed for", user.id, e);
192	  }
193	  jar.delete(REF_COOKIE);
194	  try {
195	    const { sendMail, emails } = await import("./mailer");
196	    const tpl = emails.welcome(name);
197	    await sendMail({ to: email, subject: tpl.subject, html: tpl.html, userId: user.id, kind: "welcome" });
198	  } catch { /* email is best-effort */ }
199	  // Send the verification link. Best-effort like the welcome mail and it does
200	  // NOT block the redirect: signing up and looking around stay open, only
201	  // buying and provisioning wait on the click (lib/email-verification.ts). If
202	  // this send fails the account is still usable and still resendable from the
203	  // portal banner — the customer is never stranded on a screen we control.
204	  try {
205	    const { sendVerificationEmail } = await import("./email-verification");
206	    await sendVerificationEmail(user);
207	  } catch (e) {
208	    console.error("[register] verification email failed:", e);
209	  }
210	  redirect("/dashboard");
211	}
