213	export async function login(
214	  prev: any,
215	  formData: FormData,
216	): Promise<{ error?: string; needs2fa?: boolean }> {
217	  const parsed = credsSchema.safeParse({
218	    // Same canonical form the account was stored under (lib/email-normalize.ts).
219	    // Without this, signing in as `Alice@Example.com` missed a row stored as
220	    // `alice@example.com` and reported bad credentials for a correct password.
221	    email: normalizeEmail(formData.get("email")),
222	    password: formData.get("password"),
223	  });
224	  if (!parsed.success) return { error: "Invalid email or password." };
225	
226	  // App-level throttle per email+IP over a 15 min window. The max-attempts cap is
227	  // admin-configurable (`login_ratelimit_max`, default 10) rather than hardcoded.
228	  //
229	  // The IP comes from `clientIp` (lib/rate-limit.ts), NEVER from
230	  // `x-forwarded-for.split(",")[0]`. nginx forwards the header with
231	  // `$proxy_add_x_forwarded_for`, which APPENDS the peer it saw to whatever the
232	  // client sent — so the leftmost entry is a free-text field the caller filled
233	  // in, and keying on it meant an attacker could rotate one header value per
234	  // request and never bind this limiter at all. That is the limiter standing
235	  // between a known email address and unlimited password guesses, and (below)
236	  // unlimited 2FA code guesses once a password is known. See the docblock on
237	  // `clientIp` for the measurement.
238	  const rlId = `${parsed.data.email}:${clientIp(await headers())}`;
239	  const maxAttempts = Math.max(1, await getSettingInt("login_ratelimit_max", 10));
240	  const rl = checkRateLimit(`login:${rlId}`, { max: maxAttempts, windowMs: 15 * 60 * 1000 });
241	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
242	
243	  const user = await db.user.findUnique({ where: { email: parsed.data.email } });
244	  if (!user || !(await bcrypt.compare(parsed.data.password, user.passwordHash))) {
245	    return { error: "Invalid email or password." };
246	  }
247	  if (user.suspended) return { error: "This account is suspended." };
248	
249	  // Two-factor challenge, if enabled on the account.
250	  if (user.totpEnabled) {
251	    const code = String(formData.get("code") ?? "").trim();
252	    if (!code) return { error: "Enter your 2FA code to continue.", needs2fa: true };
253	    if (!(await verifyTotpForUser(user.id, code))) {
254	      return { error: "Invalid 2FA code.", needs2fa: true };
255	    }
256	  }
257	
258	  resetRateLimit(`login:${rlId}`);
259	  await audit(user.id, "user.login");
260	  await createSession(user.id);
261	  // Land where they were HEADING, not on a generic dashboard.
262	  //
263	  // Public CTAs like "Migrate free →" send a logged-out visitor into
264	  // /dashboard/..., which bounces to /login and — until now — discarded what they
265	  // clicked. They signed in and arrived somewhere unrelated, with no route back to
266	  // the thing they wanted. Seven CTAs did this, the worst being "Contact support"
267	  // on the PUBLIC help page, where a prospect met a login wall instead of /contact.
268	  //
269	  // `safeNext` only ever returns a path on THIS site (see its definition): an
270	  // open redirect on a login form is a phishing primitive, so an absolute URL, a
271	  // protocol-relative `//evil.test` or anything that is not a single-slash path is
272	  // discarded rather than sanitised.
273	  const next = safeNext(formData.get("next"));
274	  redirect(next ?? (user.role === "ADMIN" ? "/admin" : "/dashboard"));
275	}
