284	/**
285	 * Enforce the admin-configured per-user server cap (`max_servers_per_user`,
286	 * default 10; 0 = unlimited). Counts every server the user owns that isn't being
287	 * torn down (DELETING). Returns an error message when the cap is reached, else null.
288	 */
289	async function serverLimitError(userId: string): Promise<string | null> {
290	  const cap = await getSettingInt("max_servers_per_user", 10);
291	  if (cap <= 0) return null; // 0 (or negative) = unlimited
292	  const owned = await db.server.count({ where: { userId, status: { notIn: ["DELETING"] } } });
293	  if (owned >= cap) {
294	    return `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}. Delete one or contact support to raise the cap.`;
295	  }
296	  return null;
297	}
