299	/*
300	 * `orderServer` — the wallet-only form action — WAS HERE, and was deleted on
301	 * 2026-07-27 along with its only caller, components/OrderForm.tsx. Read this
302	 * before writing anything that looks like it again.
303	 *
304	 * It was dead in the UI and live on the network. Nothing rendered OrderForm, but
305	 * lib/actions.ts carries `"use server"`, so `orderServer` remained a
306	 * network-callable endpoint that provisioned VMs and debited wallets — the same
307	 * property that made `verifyTotpForUser` a public 2FA oracle.
308	 *
309	 * And it was WRONG in three ways that only a second copy can be wrong:
310	 *
311	 *   1. DISPLAYED != CHARGED. OrderForm showed the plan's monthly list price as
312	 *      "Due today" while this action charged
313	 *      `promoPriceCents(vpsTermPriceCents(price, months), currentPromo(now))`.
314	 *      Under the Summer Sale an $8.99 plan displayed $8.99 and took $6.29. That
315	 *      is the 2026-07-25 incident verbatim, and it is what
316	 *      test/pricing-display-vs-charge.test.ts exists to stop.
317	 *   2. It had already DRIFTED from the real order core: no `extraDiskGB`, so it
318	 *      could neither sell nor charge for the deploy-time storage upsell that
319	 *      `orderQuote` prices.
320	 *   3. It skipped two guards `placeOrder` performs — `diskCapacityCheck`, and
321	 *      the `addons.dailyBackup` -> `autoBackup`/`backupIntervalHours` bridge
322	 *      (lib/order.ts). Every server in the live DB once carried
323	 *      `addons.dailyBackup` with `autoBackup: false` and no backup job ever
324	 *      enqueued: customers paid for backups they were never going to receive.
325	 *
326	 * `payAndDeploy` below is the one deploy path. It routes through lib/order.ts —
327	 * `intentFromFormData` + `orderQuote` + `placeOrder` — and covers BOTH the
328	 * wallet-funded and the card-funded case, so nothing was lost by removing this.
329	 * If a wallet-only form is ever wanted back, it must call `placeOrder`, not
330	 * recompose the price. One formula, one charge.
331	 */
332	
333	/**
334	 * Deploy flow that does NOT require pre-funding the wallet. If the wallet covers
335	 * the order (or it's a free admin grant) it provisions immediately; otherwise it
336	 * returns a Stripe Checkout URL for the order total, and the Stripe confirm route
337	 * provisions the server on successful payment.
338	 */
339	export async function payAndDeploy(
340	  prev: any,
341	  formData: FormData,
342	): Promise<{ error?: string; checkoutUrl?: string }> {
343	  const user = await requireUser();
344	  // Spend path: never move a customer's money while an admin is impersonating them.
345	  await assertNotImpersonating();
346	  // Same verification gate every purchase path applies. This is the CARD path, so it is the
347	  // one where an unreachable address is most expensive: without it we would take
348	  // a real payment for a machine whose credentials have nowhere to go.
349	  const unverified = await emailVerificationError(user);
350	  if (unverified) return { error: unverified };
351	  // Per-user server cap — the same one `orderGameServer` enforces for game tiers.
352	  const limitErr = await serverLimitError(user.id);
353	  if (limitErr) return { error: limitErr };
354	  const intent = intentFromFormData(formData);
355	
356	  let quote;
357	  try {
358	    quote = await orderQuote(intent);
359	  } catch (e) {
360	    if (e instanceof OrderError) return { error: e.message };
361	    throw e;
362	  }
363	
364	  const isAdmin = user.role === "ADMIN";
365	  const freePath = !!intent.free && isAdmin;
366	
367	  // Wallet-aware split. The customer's Review screen computes the exact same split
368	  // (lib/wallet-split.ts) from the same inputs, so what they see === what we charge.
369	  // `useWallet` defaults ON (only "0" turns it off) so existing forms keep applying
370	  // the balance. Free admin grants skip the split entirely (no money moves).
371	  const useWallet = formData.get("useWallet") !== "0";
372	  const { walletApplied, cardCents } = freePath
373	    ? { walletApplied: 0, cardCents: 0 }
374	    : walletSplit({ dueCents: quote.chargeCents, balanceCents: user.balanceCents, useWallet });
375	
376	  // Card portion is $0 (free admin grant, or the wallet fully covers the charge) →
377	  // provision straight away. placeOrder debits the FULL chargeCents from the wallet
378	  // (or nothing, for a free grant); the balance check inside it holds because a
379	  // $0 card portion means balance >= chargeCents.
380	  if (freePath || cardCents <= 0) {
381	    let serverId: string;
382	    try {
383	      serverId = await placeOrder(user, intent);
384	    } catch (e) {
385	      if (e instanceof OrderError) return { error: e.message };
386	      throw e;
387	    }
388	    redirect(`/dashboard/servers/${serverId}`);
389	  }
390	
391	  // Card portion > 0 → charge ONLY the remainder on the card (not the full total).
392	  // On payment success the confirm route credits this card amount to the wallet and
393	  // then placeOrder debits the full chargeCents, so the wallet naturally absorbs
394	  // `walletApplied` and the card the rest — the wallet is never touched before the
395	  // card clears. (walletApplied is implied by cardCents vs. the recomputed charge,
396	  // so it needs no separate metadata field.)
397	  // The price is handed over EXPLICITLY, from the very quote the wallet split above
398	  // was computed from. Without this argument `createOrderCheckout` re-quotes
399	  // internally, microseconds later, from its own `new Date()` — the same function,
400	  // so no formula can drift, but two different instants. A promo boundary (or an
401	  // operator changing a plan price) falling between them would mean the card leg
402	  // and the stamped total were priced against two different worlds, and the wallet
403	  // would silently absorb the difference. One quote, one price, one charge.
404	  const url = await createOrderCheckout(user, cardCents, intent, orderPriceOf(quote));
405	  if (!url) return { error: "Card payments aren't set up yet — top up your wallet to deploy." };
406	  return { checkoutUrl: url };
407	}
