411	async function ownedServer(serverId: string) {
412	  const user = await requireUser();
413	  const server = await db.server.findUnique({ where: { id: serverId } });
414	  if (!server) throw new Error("Not found");
415	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
416	  return { user, server };
417	}
