419	export async function serverAction(serverId: string, action: string) {
420	  const { user, server } = await ownedServer(serverId);
421	  const allowed: Record<string, "START" | "STOP" | "REBOOT" | "REINSTALL" | "DELETE"> = {
422	    start: "START",
423	    stop: "STOP",
424	    reboot: "REBOOT",
425	    reinstall: "REINSTALL",
426	    delete: "DELETE",
427	  };
428	  const type = allowed[action];
429	  if (!type) throw new Error("Invalid action");
430	  if (server.status === "SUSPENDED" && user.role !== "ADMIN") {
431	    throw new Error("Server is suspended");
432	  }
433	
434	  // A reinstall wipes the whole VM, including any block-storage volume the VM
435	  // owns (Proxmox `qm destroy --purge` frees every disk for that vmid).
436	  //
437	  // Count volumes by `serverId` ALONE, never by `status: "ATTACHED"`. Detaching
438	  // deliberately keeps `serverId` set so the volume can be re-attached
439	  // (worker/volumes.ts) — the disk stays owned by this vmid as an `unusedN`
440	  // entry, and PVE's destroy_vm frees unused disks too (include_unused => 1).
441	  // Filtering on ATTACHED therefore missed the worst case: customer fills a
442	  // volume, clicks Detach (the UI promises "Data is preserved."), clicks
443	  // Reinstall — both guards see zero attached volumes, and the purge takes the
444	  // data with it. `reinstallToOs` in actions-server-lifecycle.ts always counted
445	  // by serverId; this path did not. That asymmetry was the bug.
446	  if (type === "REINSTALL") {
447	    const pinnedVolumes = await db.volume.count({ where: { serverId } });
448	    if (pinnedVolumes > 0) {
449	      throw new Error(
450	        "Delete your data volume(s) before reinstalling — a reinstall wipes the whole server, and that includes detached volumes still assigned to it. Open Volumes first.",
451	      );
452	    }
453	  }
454	
455	  const pending = await db.job.count({
456	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
457	  });
458	  if (pending > 0) return; // debounce: one job at a time per server
459	
460	  if (type === "DELETE") {
461	    await db.server.update({ where: { id: serverId }, data: { status: "DELETING" } });
462	  }
463	  await db.job.create({ data: { type, serverId } });
464	  await audit(user.id, `server.${action}`, serverId);
465	  if (type === "DELETE") redirect(user.role === "ADMIN" ? "/admin/servers" : "/dashboard");
466	  revalidatePath(`/dashboard/servers/${serverId}`);
467	}
