471	export async function topUp(prev: any, formData: FormData): Promise<{ error?: string }> {
472	  const user = await requireUser();
473	  // Spend/credit path: block while impersonating so an admin can't mint or move
474	  // a customer's balance on their behalf.
475	  await assertNotImpersonating();
476	  // Security: never mint free wallet balance in production. The demo gateway that
477	  // credits without a real payment is only ever acceptable in non-production, and
478	  // is refused outright when NODE_ENV === "production" regardless of Stripe.
479	  if (process.env.NODE_ENV === "production") {
480	    return { error: "Please add funds with a card via the secure checkout." };
481	  }
482	  // Once Stripe is configured, the demo gateway is hard-disabled — top-ups must
483	  // go through Checkout.
484	  const { stripeConfigured } = await import("./stripe");
485	  if (stripeConfigured()) {
486	    return { error: "Please add funds with a card via the secure checkout." };
487	  }
488	  // Throttle demo top-ups per user+IP to prevent rapid free-credit minting.
489	  const topupIp = clientIp(await headers());
490	  const topupRl = checkRateLimit(`topup:${user.id}:${topupIp}`, { max: 10, windowMs: 60 * 60 * 1000 });
491	  if (!topupRl.ok) {
492	    return { error: `Too many top-up attempts. Try again in ${topupRl.retryAfterSec}s.` };
493	  }
494	  const amount = Number(formData.get("amount"));
495	  if (!Number.isFinite(amount) || amount < 1 || amount > 1000) {
496	    return { error: "Amount must be between $1 and $1000." };
497	  }
498	  const cents = Math.round(amount * 100);
499	  // Enforce the admin-configured minimum top-up (`min_topup_cents`, default 500).
500	  const minTopup = await getSettingInt("min_topup_cents", 500);
501	  if (cents < minTopup) {
502	    return { error: `Minimum top-up is $${(minTopup / 100).toFixed(2)}.` };
503	  }
504	
505	  // Optional promo code: applied via the COUPON_COOKIE the billing CouponField
506	  // sets. applyCouponToTopup re-validates for this user against the real amount.
507	  const jar = await cookies();
508	  const couponCode = jar.get(COUPON_COOKIE)?.value?.trim();
509	  let bonusCents = 0;
510	  let couponId: string | null = null;
511	  let couponLabel = "";
512	  if (couponCode) {
513	    const result = await applyCouponToTopup(couponCode, cents);
514	    if (result.ok) {
515	      bonusCents = result.bonusCents;
516	      couponId = result.couponId;
517	      couponLabel = result.label;
518	    } else {
519	      // REFUSE, don't silently drop. The old code fell through and completed the
520	      // top-up with no bonus and no message, so a code that passed validation at
521	      // the preview amount but fails against the real one (a `minAmountCents`
522	      // floor, an exhausted limit, an expiry) simply vanished — the customer paid
523	      // expecting a bonus and got nothing, with nowhere to look. Nothing has been
524	      // charged at this point, so stopping is free and the customer can retry
525	      // without the code or with a larger amount.
526	      return {
527	        error:
528	          `${result.error ?? "That promo code can't be applied to this amount."} ` +
529	          `Nothing has been charged — adjust the amount or remove the code and try again.`,
530	      };
531	    }
532	  }
533	
534	  await db.$transaction([
535	    db.user.update({
536	      where: { id: user.id },
537	      data: { balanceCents: { increment: cents + bonusCents } },
538	    }),
539	    db.walletTransaction.create({
540	      data: { userId: user.id, amountCents: cents, description: "Wallet top-up (demo gateway)" },
541	    }),
542	    ...(bonusCents > 0 && couponId
543	      ? [
544	          db.walletTransaction.create({
545	            data: {
546	              userId: user.id,
547	              amountCents: bonusCents,
548	              description: `Promo ${couponCode!.toUpperCase()} — ${couponLabel}`,
549	            },
550	          }),
551	          db.couponRedemption.create({
552	            data: { couponId, userId: user.id, amountCents: bonusCents, context: "topup" },
553	          }),
554	          db.coupon.update({
555	            where: { id: couponId },
556	            data: { timesRedeemed: { increment: 1 } },
557	          }),
558	        ]
559	      : []),
560	  ]);
561	  jar.delete(COUPON_COOKIE);
562	  await audit(user.id, "wallet.topup", `$${amount}${bonusCents > 0 ? ` +bonus $${(bonusCents / 100).toFixed(2)}` : ""}`);
563	  // First successful paid action may unlock a referral reward for both parties.
564	  try {
565	    await maybeRewardReferral(user.id);
566	  } catch { /* non-fatal */ }
567	  revalidatePath("/dashboard/billing");
568	  return {};
569	}
