584	export async function renewNow(serverId: string): Promise<{ error?: string } | void> {
585	  // Spend path: block wallet debits while an admin is impersonating.
586	  await assertNotImpersonating();
587	  const { user, server } = await ownedServer(serverId);
588	  if (server.isFree || !server.expiresAt) return;
589	  // A MANUAL renewal is a fresh purchase decision, so it is gated. Note this
590	  // cannot strand an existing customer: every account that owns a server today
591	  // predates verification and is grandfathered, and the automatic renewal in
592	  // worker/billing.ts does not pass through here at all — nobody's server lapses
593	  // because of this check.
594	  const unverified = await emailVerificationError(user);
595	  if (unverified) return { error: unverified };
596	  const plan = await db.plan.findUnique({ where: { id: server.planId } });
597	  if (!plan) return;
598	  // A game server carries BOTH a base `planId` and a `gamePlanId`, and it is sold
599	  // at the game plan's FLAT price. Reading only `plan.priceCents` here charged a
600	  // game-server owner the base VPS term price instead — `minecraft-mm8w85` sold at
601	  // $4.99 on a Starter base plan would have been billed $8.99, an 80% overcharge.
602	  const gamePlan = server.gamePlanId
603	    ? await db.gamePlan.findUnique({
604	        where: { id: server.gamePlanId },
605	        select: { name: true, priceCents: true, termMonths: true },
606	      })
607	    : null;
608	  // Charge the IP surcharge based on the ACTUAL allocated IP (matching worker/
609	  // billing.ts), not the intent flag — a NAT-fallback server never gets billed.
610	  const hasDedicatedIp = !!(await db.dedicatedIp.findFirst({
611	    where: { serverId }, select: { id: true },
612	  }));
613	  // Priced through `renewalCharge` — the SAME function the automatic renewal sweep
614	  // in worker/billing.ts and the saved-card path use. Not a second copy of the
615	  // arithmetic: see lib/renewal-quote.ts for both incidents that produced this
616	  // rule, the second of which was a fresh duplicate written hours after the first.
617	  const quote = renewalQuote(
618	    {
619	      termMonths: server.termMonths,
620	      extraDiskGB: server.extraDiskGB,
621	      plan: { name: plan.name, priceCents: plan.priceCents },
622	      gamePlan,
623	      dedicatedIp: hasDedicatedIp ? {} : null,
624	    },
625	    {
626	      ipMonthlyCents: hasDedicatedIp ? await dedicatedIpMonthlyCents() : 0,
627	      extraDiskPerGbCents: await extraDiskPerGbCents(),
628	    },
629	  );
630	  const renewCents = quote.totalCents;
631	  const term = { months: quote.months };
632	  const extraDiskMonthly = await extraDiskMonthlyCents(server.extraDiskGB);
633	  const extraDiskCents = gamePlan ? 0 : extraDiskMonthly * quote.months;
634	  const owner = await db.user.findUnique({ where: { id: server.userId } });
635	  if (!owner || owner.balanceCents < renewCents) {
636	    return { error: "Insufficient balance — top up your wallet first." };
637	  }
638	
639	  // `E` is the expiry we read OUTSIDE the transaction. We advance it with a
640	  // compare-and-swap on that exact value so two concurrent "Renew now" clicks
641	  // can't both read E, both debit, and both write E+term (double-charge, one
642	  // term granted). Only the CAS that matches E wins; the loser is a no-op.
643	  const E = server.expiresAt;
644	  const base = new Date(Math.max(E.getTime(), Date.now()));
645	  const newExpiry = addMonths(base, term.months);
646	
647	  // `renewCents` above is `vpsTermPriceCents(...)` — the REGULAR price, with no
648	  // seasonal promo applied. That is exactly what lib/promotions.ts promises: the
649	  // strikethrough on the marketing page is the real renewal price. So the months
650	  // being added here are sold at 0% off, and the term's stored rate has to say so.
651	  //
652	  // BLENDED, not overwritten. A customer can renew early, stacking a full-price
653	  // term on top of months still running at an intro discount. Overwriting would
654	  // silently reprice those earlier months to full list — and that is the profitable
655	  // direction: buy 36 months at 45% off, renew once at full price, and every one of
656	  // the original discounted months would suddenly credit at the full rate on a
657	  // downgrade. Blending keeps the cash value of the window invariant.
658	  const renewedPercent = prorateBlendPercent({
659	    currentPercent: resolveTermPromoPercent(server.termPromoPercent),
660	    currentMonths: remainingMonths(E, Date.now()),
661	    addedPercent: 0,
662	    addedMonths: term.months,
663	  });
664	  try {
665	    await db.$transaction(async (tx) => {
666	      // Compare-and-swap the expiry first; if it no longer equals E another
667	      // renewal already advanced it — bail without charging (tx rolls back).
668	      const adv = await tx.server.updateMany({
669	        where: { id: serverId, expiresAt: E },
670	        data: {
671	          expiresAt: newExpiry,
672	          termPromoPercent: renewedPercent,
673	          suspendedNote: null,
674	          suspendReason: null,
675	        },
676	      });
677	      if (adv.count === 0) throw new AlreadyRenewedError();
678	      // Atomic guarded debit: a concurrent spend can't drive the wallet negative.
679	      await debitWallet(tx, server.userId, renewCents);
680	      await tx.walletTransaction.create({
681	        data: {
682	          userId: server.userId,
683	          amountCents: -renewCents,
684	          description: `Renewal: ${quote.label} (${server.hostname}) — ${quote.durationLabel}`,
685	        },
686	      });
687	      // PAID invoice inside the same CAS-guarded tx: a losing concurrent "Renew
688	      // now" throws AlreadyRenewedError and rolls back, so no duplicate invoice.
689	      await tx.invoice.create({
690	        data: invoiceCreateData({
691	          userId: server.userId,
692	          description: `Renewal: ${quote.label} (${server.hostname}) — ${quote.durationLabel}`,
693	          status: "PAID",
694	          period: { start: E, end: newExpiry },
695	          lineItems: [
696	            {
697	              description: `${quote.label} (${server.hostname}) — ${quote.durationLabel}`,
698	              qty: 1,
699	              unitCents: renewCents - extraDiskCents,
700	              amountCents: renewCents - extraDiskCents,
701	            },
702	            ...(extraDiskCents > 0
703	              ? [
704	                  {
705	                    description: `${extraDiskLabel(server.extraDiskGB)} — ${server.hostname} (permanent, $${(extraDiskMonthly / 100).toFixed(2)}/mo)`,
706	                    qty: 1,
707	                    unitCents: extraDiskCents,
708	                    amountCents: extraDiskCents,
709	                  },
710	                ]
711	              : []),
712	          ],
713	        }),
714	      });
715	    });
716	  } catch (e) {
717	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
718	    if (e instanceof AlreadyRenewedError) return { error: "This server was just renewed — refresh to see the new expiry." };
719	    throw e;
720	  }
721	  await audit(user.id, "server.renew_now", serverId);
722	
723	  // An UNPAID-suspended server springs back to life once paid — but only that
724	  // kind. This used to fire for ANY suspended server, so a customer suspended for
725	  // outbound abuse could click "Renew now", pay, and put themselves straight back
726	  // on the network, undoing an abuse or admin action with a card. Legacy rows with
727	  // a null `suspendReason` are not auto-lifted; an admin can clear those by hand.
728	  if (server.status === "SUSPENDED" && server.suspendReason === "UNPAID") {
729	    const pending = await db.job.count({
730	      where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
731	    });
732	    if (pending === 0) await db.job.create({ data: { type: "UNSUSPEND", serverId } });
733	  }
734	  revalidatePath(`/dashboard/servers/${serverId}`);
735	}
