739	export async function adminExtendServer(prev: any, formData: FormData): Promise<{ error?: string }> {
740	  const admin = await requireAdmin();
741	  const serverId = String(formData.get("serverId") ?? "");
742	  const days = Number(formData.get("days"));
743	  if (!serverId || !Number.isFinite(days) || days === 0 || Math.abs(days) > 365) {
744	    return { error: "Days must be between -365 and 365." };
745	  }
746	  const server = await db.server.findUnique({ where: { id: serverId } });
747	  if (!server) return { error: "Server not found." };
748	  const base = server.expiresAt ? server.expiresAt.getTime() : Date.now();
749	
750	  // ─── EXPIRESAT INTEGRITY ────────────────────────────────────────────────────
751	  // The whole proration model rests on "every month between now and `expiresAt` is
752	  // a month the customer has actually bought" (see lib/proration.ts
753	  // remainingMonths). This action moves `expiresAt` by up to a year per call, with
754	  // no call limit and no payment — so before the persisted rate existed, an admin
755	  // goodwill gift of 12 months was directly convertible to cash: downgrade the
756	  // gifted server and the prorated credit paid out real wallet money for months
757	  // nobody had ever been charged for. Admin-only, so never a self-service exploit,
758	  // but a support agent clicking "extend" was minting refundable balance.
759	  //
760	  // SEMANTICS CHOSEN: gifted months are recorded as sold at 100% off, and blended
761	  // into the rate the existing months are on. That is the honest reading of a gift
762	  // — those months cost the customer nothing, so nothing may prorate out of them —
763	  // and it is exact rather than blunt: the blend leaves the CASH VALUE of the
764	  // remaining window completely unchanged, so a customer who paid for 12 months and
765	  // was gifted a 13th still gets back precisely what those 12 paid months are worth
766	  // on a downgrade. Zeroing the whole term instead would confiscate what they paid;
767	  // leaving the rate alone is the money printer. Repeated gifts only ever dilute
768	  // toward 100, so no number of calls can raise the payout.
769	  //
770	  // A NEGATIVE `days` removes months rather than adding them, so there is nothing
771	  // to blend in: the customer keeps the rate they bought at over a shorter window,
772	  // which strictly reduces any future credit. Blending negative months would push
773	  // the rate the other way and over-credit what is left.
774	  const gifted = days > 0;
775	  const termPromoPercent = gifted
776	    ? prorateBlendPercent({
777	        currentPercent: resolveTermPromoPercent(server.termPromoPercent),
778	        currentMonths: remainingMonths(server.expiresAt, Date.now()),
779	        addedPercent: 100, // gifted: no cash changed hands for these months
780	        addedMonths: (days * 86400_000) / MS_PER_AVG_MONTH,
781	      })
782	    : resolveTermPromoPercent(server.termPromoPercent);
783	
784	  await db.server.update({
785	    where: { id: serverId },
786	    data: { expiresAt: new Date(base + days * 86400_000), termPromoPercent },
787	  });
788	  await audit(
789	    admin.id,
790	    "admin.extend_server",
791	    `${serverId} ${days}d${gifted ? ` gifted (rate basis ${server.termPromoPercent ?? "null"}% -> ${termPromoPercent}% off)` : ""}`,
792	  );
793	  revalidatePath("/admin/subscriptions");
794	  return {};
795	}
