856	export async function adminSuspendServer(serverId: string, suspend: boolean) {
857	  const admin = await requireAdmin();
858	  // Record WHY. An admin suspension is NOT an unpaid one: the renewal sweep skips
859	  // suspended servers, so a paid-up customer suspended here is never charged and
860	  // never warned — and before `suspendReason` existed, `terminateOverdue` then
861	  // deleted their VM and all its data once the untouched term lapsed. Tagging it
862	  // ADMIN keeps the terminator away from it and stops "Renew now" silently
863	  // reversing an administrative decision.
864	  await db.server.update({
865	    where: { id: serverId },
866	    data: suspend
867	      ? { suspendReason: "ADMIN", suspendedNote: "suspended by support — contact us to restore access" }
868	      : { suspendReason: null, suspendedNote: null },
869	  });
870	  await db.job.create({ data: { type: suspend ? "SUSPEND" : "UNSUSPEND", serverId } });
871	  await audit(admin.id, suspend ? "admin.suspend_server" : "admin.unsuspend_server", serverId);
872	  revalidatePath("/admin/servers");
873	}
