2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "@/lib/db";
5	import { requireArea } from "@/lib/rbac";
6	import { stripe, stripeConfigured } from "@/lib/stripe";
7	
8	/**
9	 * Admin power-tools for finance ops: refunds, manual balance adjustments and
10	 * bulk invoice/client actions. Every action is gated by `requireArea("billing")`
11	 * (bulk-suspend is a clients-area capability and gates on "clients") and writes
12	 * an AuditLog row.
13	 *
14	 * The existing single-invoice void / mark-paid live in `lib/actions-billing.ts`
15	 * and are consumed directly from there (a "use server" file cannot re-export).
16	 */
17	
18	async function audit(userId: string | null, action: string, detail?: string) {
19	  await db.auditLog.create({ data: { userId, action, detail } });
20	}
21	
22	/**
23	 * Raised (and caught in the same function) when the compare-and-swap on an
24	 * invoice's `refundedCents` loses — i.e. another request already recorded this
25	 * refund step. Module-local, not an export: every EXPORT of a "use server" file
26	 * becomes a network-callable endpoint and must be an async function.
27	 */
28	class AlreadyRefundedError extends Error {}
29	
30	function parseAmountCents(raw: FormDataEntryValue | null): number | null {
31	  const amount = Number(raw);
32	  if (!Number.isFinite(amount) || amount === 0) return null;
33	  if (Math.abs(amount) > 50000) return null; // sanity cap: $50k / action
34	  return Math.round(amount * 100);
35	}
36	
37	/** Pull a Stripe checkout-session id (cs_...) out of a wallet-transaction note. */
38	function sessionIdFrom(description: string | undefined | null): string | null {
39	  const m = (description ?? "").match(/cs_[A-Za-z0-9_]+/);
40	  return m ? m[0] : null;
41	}
42	
43	/**
44	 * Refund a customer. When the top-up can be traced back to a Stripe Checkout
45	 * session (its wallet ledger row carries `Stripe payment (cs_...)`) and Stripe
46	 * is configured, the money is returned to the original card via the recovered
47	 * PaymentIntent. Otherwise we fall back to a **wallet-only** refund which simply
48	 * debits the wallet balance and records the ledger entry.
49	 *
50	 * Safety: the wallet is never driven below zero — for a wallet-only refund we
51	 * require sufficient balance; for a Stripe refund of already-spent funds we
52	 * decrement only what remains (the rest is a real-cash write-off) and note it.
53	 */
54	export async function refundPayment(
55	  _prev: unknown,
56	  formData: FormData
57	): Promise<{ error?: string; message?: string }> {
58	  const admin = await requireArea("billing");
59	
60	  const userId = String(formData.get("userId") ?? "");
61	  const reason = String(formData.get("reason") ?? "").trim().slice(0, 200);
62	  const cents = parseAmountCents(formData.get("amount"));
63	  // The invoice this refund is FOR. The UI has always rendered the control under a
64	  // heading naming one invoice, pre-filled with that invoice's total — but the id
65	  // was never sent, so the action guessed its Stripe target as "most recent top-up,
66	  // any amount". Refunding a $24 March invoice therefore issued $24 against the
67	  // customer's $200 July top-up, left the invoice PAID, and invited the next admin
68	  // to refund it all over again.
69	  const invoiceId = String(formData.get("invoiceId") ?? "").trim();
70	
71	  if (!userId) return { error: "Missing customer." };
72	  if (cents === null || cents < 0) return { error: "Enter a positive refund amount (max $50,000)." };
73	
74	  const user = await db.user.findUnique({ where: { id: userId } });
75	  if (!user) return { error: "Customer not found." };
76	
77	  // Resolve and validate the target invoice when one was supplied.
78	  let invoice = null as Awaited<ReturnType<typeof db.invoice.findUnique>>;
79	  // How much of the invoice was already refunded WHEN WE READ IT. Two jobs: it is
80	  // the compare-and-swap anchor for the write below, and it is what makes the
81	  // Stripe idempotency key describe a STEP of the refund rather than an amount.
82	  let alreadyRefunded = 0;
83	  if (invoiceId) {
84	    invoice = await db.invoice.findUnique({ where: { id: invoiceId } });
85	    if (!invoice) return { error: "Invoice not found." };
86	    if (invoice.userId !== userId) return { error: "That invoice belongs to a different customer." };
87	    alreadyRefunded = invoice.refundedCents ?? 0;
88	    const refundable = Math.max(0, invoice.amountCents - alreadyRefunded);
89	    if (refundable === 0) {
90	      return { error: `Invoice already fully refunded ($${(alreadyRefunded / 100).toFixed(2)}).` };
91	    }
92	    if (cents > refundable) {
93	      return {
94	        error: `That exceeds what's left on this invoice — $${(refundable / 100).toFixed(2)} refundable ($${(alreadyRefunded / 100).toFixed(2)} already refunded).`,
95	      };
96	    }
97	  }
98	
99	  // --- Route the refund back to the ORIGINAL card for this charge ---
100	  let method: "stripe" | "wallet" = "wallet";
101	  let stripeRefundId: string | null = null;
102	  if (stripeConfigured()) {
103	    // Prefer the charge that actually paid THIS invoice; only fall back to the
104	    // latest top-up when no invoice was specified (the standalone refund form).
105	    const tx = await db.walletTransaction.findFirst({
106	      where: invoice
107	        ? {
108	            userId,
109	            description: { contains: "Stripe payment (cs_" },
110	            createdAt: { lte: invoice.paidAt ?? invoice.createdAt },
111	          }
112	        : { userId, description: { contains: "Stripe payment (cs_" } },
113	      orderBy: { createdAt: "desc" },
114	    });
115	    const sessionId = sessionIdFrom(tx?.description);
116	    if (sessionId) {
117	      try {
118	        const session = await stripe().checkout.sessions.retrieve(sessionId);
119	        const pi =
120	          typeof session.payment_intent === "string"
121	            ? session.payment_intent
122	            : session.payment_intent?.id;
123	        if (pi) {
124	          // Idempotency key derived from the target, the amount AND how much of
125	          // this invoice had already been refunded when this request read it.
126	          //
127	          // The first two alone (`refund:<target>:<pi>:<cents>`) deduplicated two
128	          // submits — which is the point — but they ALSO deduplicated two genuinely
129	          // different refunds that happened to be the same size. Two $10 partial
130	          // refunds against a $100 invoice are a completely ordinary support
131	          // sequence, and Stripe replayed the first refund for the second: ONE $10
132	          // refund reached the card while this action debited the customer's wallet
133	          // $10 twice and recorded $20 against the invoice. The customer was $10
134	          // down, and the two systems agreed with each other about it.
135	          //
136	          // `alreadyRefunded` is 0 then 10 across those two calls, so they are
137	          // distinct requests; a true double-submit reads the same value and still
138	          // collapses to one refund. (Standalone refunds with no invoice keep the
139	          // old shape — there is no per-target running total to anchor to.)
140	          const refund = await stripe().refunds.create(
141	            { payment_intent: pi, amount: cents },
142	            {
143	              idempotencyKey: invoiceId
144	                ? `refund:${invoiceId}:${pi}:${alreadyRefunded}:${cents}`
145	                : `refund:${userId}:${pi}:${cents}`,
146	            }
147	          );
148	          stripeRefundId = refund.id;
149	          method = "stripe";
150	        }
151	      } catch {
152	        // Stripe refund failed / not refundable — fall back to wallet-only.
153	        method = "wallet";
154	      }
155	    }
156	  }
157	
158	  const available = Math.max(0, user.balanceCents);
159	  const walletDebit = Math.min(cents, available);
160	  if (method === "wallet" && walletDebit < cents) {
161	    return {
162	      error:
163	        "Insufficient wallet balance for a wallet-only refund. Use a negative balance adjustment to force it.",
164	    };
165	  }
166	
167	  const writeOff = cents - walletDebit; // real cash returned that the wallet couldn't cover
168	  const noteBits = [
169	    method === "stripe" ? `Stripe refund ${stripeRefundId}` : "wallet-only refund",
170	    invoice ? `invoice ${invoice.number ?? invoice.id}` : null,
171	    reason,
172	  ].filter(Boolean);
173	  const description = `Refund — ${noteBits.join(" · ")}`;
174	
175	  try {
176	    await db.$transaction(async (tx) => {
177	      // COMPARE-AND-SWAP on the invoice's running refunded total, and it goes FIRST
178	      // so that losing it writes nothing at all.
179	      //
180	      // Two admins (or one admin in two tabs) both read `refundedCents: 0`, both send
181	      // the same $10 refund, and Stripe — correctly — returns ONE refund for the two
182	      // identical idempotency keys. Without this guard both requests then ran the
183	      // block below: two wallet debits and two ledger rows for one real refund, while
184	      // `refundedCents` ended at 10 because each computed it from the same stale read.
185	      // History, balance and the card all disagreed. Only the update that still sees
186	      // the value it read may proceed.
187	      if (invoice) {
188	        const total = alreadyRefunded + cents;
189	        const advanced = await tx.invoice.updateMany({
190	          where: { id: invoice.id, refundedCents: alreadyRefunded },
191	          data: {
192	            refundedCents: total,
193	            ...(total >= invoice.amountCents ? { status: "REFUNDED" as const } : {}),
194	          },
195	        });
196	        if (advanced.count === 0) throw new AlreadyRefundedError();
197	      }
198	      if (walletDebit > 0) {
199	        await tx.user.update({
200	          where: { id: userId },
201	          data: { balanceCents: { decrement: walletDebit } },
202	        });
203	      }
204	      // The ledger row must equal the ACTUAL balance change. It used to record the
205	      // full refund (-cents) while the balance only fell by what was available, so a
206	      // $50 card refund against a $5 wallet left history and balance disagreeing by
207	      // $45 permanently. The uncovered remainder is a real-cash write-off and gets
208	      // its own zero-balance-effect line, so the story is legible without lying
209	      // about the arithmetic.
210	      if (walletDebit > 0) {
211	        await tx.walletTransaction.create({
212	          data: { userId, amountCents: -walletDebit, description },
213	        });
214	      }
215	      if (writeOff > 0) {
216	        await tx.walletTransaction.create({
217	          data: {
218	            userId,
219	            amountCents: 0,
220	            description:
221	              `Write-off — $${(writeOff / 100).toFixed(2)} of this refund was returned to the card ` +
222	              `beyond the wallet balance, so no wallet deduction applies to that portion. ` +
223	              noteBits.join(" · "),
224	          },
225	        });
226	      }
227	    });
228	  } catch (e) {
229	    if (e instanceof AlreadyRefundedError) {
230	      return {
231	        error:
232	          "This invoice was refunded by another request a moment ago — reload to see the current " +
233	          "refunded total before issuing another. Nothing was charged or debited twice.",
234	      };
235	    }
236	    throw e;
237	  }
238	
239	  await audit(
240	    admin.id,
241	    "billing.refund",
242	    `user=${user.email} $${(cents / 100).toFixed(2)} via ${method}${
243	      stripeRefundId ? ` (${stripeRefundId})` : ""
244	    }`
