// Pure-fs static scan: for every exported async function in a "use server" file,
// report the first authorisation-ish call inside its body. No imports of app code.
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";

const ROOT = "/opt/nxeon/lib";
const GUARD = /(requireAdmin|requireStaff|requireArea|requireUser|realUser|currentUser|assertNotImpersonating|ownedServer|ownServer|assertOwner)\s*\(/;

const rows = [];
for (const f of readdirSync(ROOT).filter((f) => f.endsWith(".ts"))) {
  const src = readFileSync(join(ROOT, f), "utf8");
  if (!/^\s*["']use server["']/m.test(src.split("\n").slice(0, 4).join("\n"))) continue;
  const lines = src.split("\n");
  for (let i = 0; i < lines.length; i++) {
    const m = lines[i].match(/^export async function (\w+)/);
    if (!m) continue;
    // walk forward to the closing brace at column 0
    let guard = null;
    let guardLine = null;
    for (let j = i + 1; j < lines.length; j++) {
      if (/^}/.test(lines[j])) break;
      if (/^export /.test(lines[j])) break;
      const g = lines[j].match(GUARD);
      if (g) { guard = g[1]; guardLine = j + 1; break; }
    }
    rows.push({ file: `lib/${f}`, line: i + 1, fn: m[1], guard, guardLine });
  }
}
const bad = rows.filter((r) => !r.guard);
console.log("=== EXPORTED SERVER ACTIONS WITH NO GUARD CALL IN BODY ===");
for (const r of bad) console.log(`${r.file}:${r.line} ${r.fn}`);
console.log(`\ntotal actions: ${rows.length}, unguarded: ${bad.length}`);

