19	export async function resolveAlert(id: string): Promise<{ ok?: boolean; error?: string }> {
20	  await requireArea("fleet");
21	  await db.abuseAlert.update({ where: { id }, data: { status: "RESOLVED", resolvedAt: new Date() } });
