// For every admin page: its requireArea(), and the guard of every server action
// reachable from it (directly or through a component it renders, one level deep
// through components/**). Pure fs/regex; imports nothing from the app.
import { readdirSync, readFileSync, statSync, existsSync } from "node:fs";
import { join } from "node:path";

const ROOT = "/opt/nxeon";
const AREA_ROLES = {
  overview: ["SUPPORT", "BILLING", "ADMIN"],
  analytics: ["ADMIN"],
  clients: ["SUPPORT", "ADMIN"],
  support: ["SUPPORT", "ADMIN"],
  fleet: ["ADMIN"],
  billing: ["BILLING", "ADMIN"],
  platform: ["ADMIN"],
};
const rolesOf = (g) => {
  if (!g) return null;
  if (g.kind === "admin") return ["ADMIN"];
  if (g.kind === "staff") return ["SUPPORT", "BILLING", "ADMIN"];
  if (g.kind === "area") return AREA_ROLES[g.area] ?? null;
  return null;
};

function walk(dir, out = []) {
  for (const e of readdirSync(dir)) {
    const p = join(dir, e);
    if (statSync(p).isDirectory()) walk(p, out);
    else if (/\.tsx?$/.test(p)) out.push(p);
  }
  return out;
}

// --- index every exported server action and its guard ---
const actionGuard = new Map(); // name -> {file, guard}
for (const f of readdirSync(join(ROOT, "lib")).filter((x) => x.endsWith(".ts"))) {
  const src = readFileSync(join(ROOT, "lib", f), "utf8");
  if (!/["']use server["']/.test(src.slice(0, 200))) continue;
  const lines = src.split("\n");
  for (let i = 0; i < lines.length; i++) {
    const m = lines[i].match(/^export async function (\w+)/);
    if (!m) continue;
    let guard = null;
    for (let j = i + 1; j < Math.min(lines.length, i + 40); j++) {
      if (/^export async function /.test(lines[j])) break;
      let g;
      if ((g = lines[j].match(/requireArea\(\s*["'](\w[\w-]*)["']/))) { guard = { kind: "area", area: g[1] }; break; }
      if (/requireArea\(\s*area\s*\)/.test(lines[j])) { guard = { kind: "area", area: "<dynamic>" }; break; }
      if (/requireAdmin\(/.test(lines[j])) { guard = { kind: "admin" }; break; }
      if (/requireStaff\(/.test(lines[j])) { guard = { kind: "staff" }; break; }
      if (/requireUser\(/.test(lines[j])) { guard = { kind: "user" }; break; }
    }
    actionGuard.set(m[1], { file: `lib/${f}`, guard });
  }
}

// --- map component file -> actions it imports ---
const compActions = new Map();
for (const p of walk(join(ROOT, "components"))) {
  const src = readFileSync(p, "utf8");
  const names = [];
  for (const m of src.matchAll(/import\s*\{([^}]*)\}\s*from\s*["']@\/lib\/(actions[\w-]*)["']/g)) {
    for (const n of m[1].split(",")) {
      const t = n.trim().split(/\s+as\s+/)[0].trim();
      if (t) names.push(t);
    }
  }
  compActions.set(p.replace(ROOT + "/", ""), names);
}

// --- for each admin page, area + actions ---
const rows = [];
for (const p of walk(join(ROOT, "app/admin")).filter((p) => /page\.tsx$/.test(p))) {
  const rel = p.replace(ROOT + "/", "");
  const src = readFileSync(p, "utf8");
  const am = src.match(/requireArea\(\s*["']([\w-]+)["']/);
  const area = am ? am[1] : "<none>";
  const actions = new Set();
  for (const m of src.matchAll(/import\s*\{([^}]*)\}\s*from\s*["']@\/lib\/(actions[\w-]*)["']/g))
    for (const n of m[1].split(",")) { const t = n.trim(); if (t) actions.add(t); }
  // components rendered by this page
  for (const m of src.matchAll(/from\s*["']@\/(components\/[\w./[\]-]+)["']/g)) {
    const cf = m[1].endsWith(".tsx") ? m[1] : `${m[1]}.tsx`;
    for (const [k, v] of compActions) if (k === cf) v.forEach((a) => actions.add(a));
    // nested: components that import other components
    const abs = join(ROOT, cf);
    if (existsSync(abs)) {
      const csrc = readFileSync(abs, "utf8");
      for (const mm of csrc.matchAll(/from\s*["']@\/(components\/[\w./[\]-]+)["']/g)) {
        const cf2 = mm[1].endsWith(".tsx") ? mm[1] : `${mm[1]}.tsx`;
        for (const [k, v] of compActions) if (k === cf2) v.forEach((a) => actions.add(a));
      }
    }
  }
  for (const a of actions) {
    const info = actionGuard.get(a);
    if (!info) continue;
    const pageRoles = AREA_ROLES[area];
    const actRoles = rolesOf(info.guard);
    if (!pageRoles || !actRoles) { rows.push({ rel, area, a, info, verdict: "?" }); continue; }
    const stricter = pageRoles.filter((r) => !actRoles.includes(r));
    const looser = actRoles.filter((r) => !pageRoles.includes(r));
    let verdict = "match";
    if (stricter.length) verdict = `ACTION STRICTER — ${stricter.join("/")} sees the control, action refuses`;
    if (looser.length) verdict = `ACTION LOOSER — ${looser.join("/")} may call it without page access`;
    rows.push({ rel, area, a, info, verdict });
  }
}

for (const r of rows.filter((r) => r.verdict !== "match").sort((a, b) => a.rel.localeCompare(b.rel)))
  console.log(`${r.rel} [${r.area}]  ${r.a}  (${r.info.file}, ${JSON.stringify(r.info.guard)})\n    -> ${r.verdict}`);
console.log(`\nchecked ${rows.length} page/action pairs; ${rows.filter((r) => r.verdict !== "match").length} mismatched`);

