import Link from "next/link";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge } from "@/components/ui/primitives";
import { actingAdminId, detailWithoutActor } from "@/lib/admin-metrics";

export const dynamic = "force-dynamic";

export default async function AdminAudit() {
  await requireArea("platform");
  const logs = await db.auditLog.findMany({
    include: { user: { select: { email: true, id: true } } },
    orderBy: { createdAt: "desc" },
    take: 200,
  });

  /*
   * IMPERSONATION ATTRIBUTION.
   *
   * `audit()` in lib/actions.ts deliberately keeps `userId` pointing at the
   * impersonated CUSTOMER (the row belongs to their account) and records who
   * actually acted by appending ` actingAdmin=<id>` to `detail`.
   *
   * This page — the one surface whose entire job is answering "who did this?" —
   * rendered `userId`'s email in the Actor column and put `detail` in a
   * `max-w-md truncate` cell. So an action an admin took while impersonating
   * displayed the CUSTOMER as the actor, and the marker naming the real admin was
   * appended at the END of exactly the string being clipped. The accountability
   * mechanism worked; the console reported the opposite of what it recorded.
   *
   * The real admin is now resolved to an email and shown as the Actor, with an
   * "impersonating <customer>" badge, and the marker is stripped out of the Detail
   * column so it is stated once, legibly, instead of hidden in truncated text.
   */
  const actorIds = [...new Set(logs.map((l) => actingAdminId(l.detail)).filter(Boolean))] as string[];
  const actors = new Map(
    (actorIds.length > 0
      ? await db.user.findMany({ where: { id: { in: actorIds } }, select: { id: true, email: true } })
      : []
    ).map((u) => [u.id, u.email]),
  );

  const impersonated = logs.filter((l) => actingAdminId(l.detail)).length;

  return (
    <div className="space-y-6">
      <PageHeader title="Audit log" sub={`Last ${logs.length} recorded actions across the platform.`}>
        {impersonated > 0 ? (
          <Badge tone="amber">{impersonated} taken while impersonating</Badge>
        ) : (
          <Badge tone="slate">no impersonated actions</Badge>
        )}
      </PageHeader>

      <div className="card overflow-x-auto p-0">
        <table className="table-shell">
          <thead>
            <tr>
              <th>Time</th>
              <th>Actor</th>
              <th>Action</th>
              <th>Detail</th>
            </tr>
          </thead>
          <tbody>
            {logs.length === 0 && (
              <tr>
                <td colSpan={4} className="py-10 text-center text-slate-500">
                  Nothing recorded yet.
                </td>
              </tr>
            )}
            {logs.map((l) => {
              const asAdmin = actingAdminId(l.detail);
              const detail = asAdmin ? detailWithoutActor(l.detail) : (l.detail ?? "");
              return (
                <tr key={l.id}>
                  <td className="whitespace-nowrap text-slate-400">
                    {l.createdAt.toISOString().replace("T", " ").slice(0, 19)}
                  </td>
                  <td>
                    {asAdmin ? (
                      <div className="flex flex-wrap items-center gap-2">
                        <Link href={`/admin/users/${asAdmin}`} className="hover:text-brand-300">
                          {actors.get(asAdmin) ?? asAdmin}
                        </Link>
                        <Badge tone="amber">impersonating {l.user?.email ?? "customer"}</Badge>
                      </div>
                    ) : l.user ? (
                      <Link href={`/admin/users/${l.user.id}`} className="hover:text-brand-300">
                        {l.user.email}
                      </Link>
                    ) : (
                      <span className="text-slate-500">system</span>
                    )}
                  </td>
                  <td className="font-mono text-xs">{l.action}</td>
                  <td className="max-w-md truncate text-slate-400" title={detail}>
                    {detail}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

